@import url('https://fonts.googleapis.com/css2?family=Hind:wght@400;500;600;700&family=JetBrains+Mono:wght@400;500;600;700&display=swap');

/* Signal DNA — quiet white, trusted blue, bubbles with nothing to hide */
.theme-signal-dna {
  --bg: oklch(1.000 0 0);
  --surface: oklch(0.973 0 0);
  --surface-2: oklch(0.940 0 0);
  --fg: oklch(0.223 0.004 286.1);
  --fg-muted: oklch(0.540 0.008 286.1);
  --accent: oklch(0.594 0.194 262.4);
  --accent-fg: oklch(1.000 0 0);
  --accent-2: oklch(0.565 0.207 262.4);
  --line: oklch(0.907 0 0);
  --success: oklch(0.673 0.162 144.2);
  --warning: oklch(0.768 0.158 81.3);
  --danger: oklch(0.643 0.215 28.8);
  --radius: 1rem;
  --radius-sm: 0.5rem;
  --radius-lg: 1.25rem;
  --radius-pill: 9999px;
  --shadow-1: 0 1px 2px oklch(0 0 0 / 8%);
  --shadow-2: 0 6px 20px -8px oklch(0 0 0 / 15%);
  --shadow-3: 0 20px 50px -16px oklch(0 0 0 / 20%);
  --glow: 0 0 0 1px color-mix(in oklab, var(--accent) 45%, transparent);
  --border-width: 1px;
  --blur-amount: 0px;
  --font-display: "Hind", sans-serif;
  --font-body: "Hind", sans-serif;
  --font-mono: "JetBrains Mono", ui-monospace, monospace;
  --tracking-display: -0.01em;
  --label-transform: none;
  --label-tracking: 0.04em;

  background-color: var(--bg);
  color: var(--fg);
  font-family: var(--font-body);
}

.theme-signal-dna h1,
.theme-signal-dna h2,
.theme-signal-dna h3 {
  font-family: var(--font-display);
  letter-spacing: var(--tracking-display);
}

/* signature */
.theme-signal-dna h1 { font-weight: 600; }
.theme-signal-dna button { font-weight: 600; }
.theme-signal-dna *, .theme-signal-dna *::before { transition-duration: 80ms; }

/* depth */
.theme-signal-dna thead th { font-weight: 600; color: var(--fg-muted); border-bottom: 1px solid var(--line); }
.theme-signal-dna td { border-bottom: 1px solid var(--line); }
.theme-signal-dna tbody tr:hover { background: var(--surface); }
.theme-signal-dna a { color: var(--accent); text-decoration: underline dotted; text-underline-offset: 3px; } /* sealed until touched */
.theme-signal-dna a:hover { text-decoration: underline solid; }
.theme-signal-dna input, .theme-signal-dna select { background: var(--surface); border: 1px solid transparent; border-radius: var(--radius-pill); }
.theme-signal-dna textarea { background: var(--surface); border: 1px solid transparent; border-radius: var(--radius-lg); }
.theme-signal-dna input:focus-visible, .theme-signal-dna textarea:focus-visible, .theme-signal-dna select:focus-visible { outline: none; border-color: var(--accent); box-shadow: var(--glow); }
.theme-signal-dna kbd { font-family: var(--font-body); font-size: 0.85em; background: var(--surface-2); border-radius: 0.4rem; padding: 0.1em 0.5em; }
.theme-signal-dna ::selection { background: oklch(0.88 0.05 262); }
.theme-signal-dna ::-webkit-scrollbar { width: 8px; height: 8px; }
.theme-signal-dna ::-webkit-scrollbar-track { background: transparent; }
.theme-signal-dna ::-webkit-scrollbar-thumb { background: oklch(0.82 0 0); border-radius: 4px; }
.theme-signal-dna .label-caps { color: var(--fg-muted); font-weight: 600; }
.theme-signal-dna .themed-border { border: 1px solid var(--line); border-radius: var(--radius-lg); border-bottom-left-radius: 0.25rem; } /* quiet bubble */
.theme-signal-dna button:active { opacity: 0.85; }

/* alt mode: Signal dark — near-neutral black, blue lifted for contrast */
.theme-signal-dna.alt-mode {
  --bg: oklch(0.145 0.000 0.0);
  --surface: oklch(0.185 0.000 0.0);
  --surface-2: oklch(0.225 0.000 0.0);
  --accent: oklch(0.664 0.160 262.0);
  --accent-2: oklch(0.72 0.14 262);
  --fg: oklch(0.97 0.005 90);
  --fg-muted: oklch(0.70 0.01 90);
  --line: oklch(1 0 0 / 14%);
  --shadow-1: 0 2px 6px oklch(0 0 0 / 45%);
  --shadow-2: 0 8px 24px oklch(0 0 0 / 55%);
  --shadow-3: 0 24px 56px oklch(0 0 0 / 65%);
}
.theme-signal-dna.alt-mode ::selection { background: oklch(0.42 0.10 262); }
.theme-signal-dna.alt-mode ::-webkit-scrollbar-thumb { background: oklch(0.42 0 0); }

/* Bridge shadcn semantic variables to the theme tokens so stock shadcn/ui
   components are skinned by the theme. Scope-safe: applies inside the theme
   class only. */
[class*="theme-"] {
  --background: var(--bg);
  --foreground: var(--fg);
  --card: var(--surface);
  --card-foreground: var(--fg);
  --popover: var(--surface);
  --popover-foreground: var(--fg);
  --primary: var(--accent);
  --primary-foreground: var(--accent-fg);
  --secondary: var(--surface-2);
  --secondary-foreground: var(--fg);
  --muted: var(--surface-2);
  --muted-foreground: var(--fg-muted);
  --accent-foreground: var(--accent-fg);
  --border: var(--line);
  --input: var(--line);
  --ring: var(--accent);
  --destructive: var(--danger);
  --destructive-foreground: var(--accent-fg);

  /* Full app surface: sidebar, charts, app-level font + shadow + tracking vars.
     These are what real products (shadcn full kit, RootCX-style UI kits) consume —
     without them a retrofit looks half-themed. */
  --sidebar: var(--surface-2);
  --sidebar-foreground: var(--fg);
  --sidebar-primary: var(--accent);
  --sidebar-primary-foreground: var(--accent-fg);
  --sidebar-accent: color-mix(in oklab, var(--accent) 12%, var(--surface-2));
  --sidebar-accent-foreground: var(--fg);
  --sidebar-border: var(--line);
  --sidebar-ring: var(--accent);

  --chart-1: var(--accent);
  --chart-2: var(--accent-2);
  --chart-3: var(--success);
  --chart-4: var(--warning);
  --chart-5: var(--danger);

  --font-sans: var(--font-body);
  --font-heading: var(--font-display);
  --font-serif: var(--font-display);

  --shadow-2xs: var(--shadow-1);
  --shadow-xs: var(--shadow-1);
  --shadow-sm: var(--shadow-1);
  --shadow: var(--shadow-2);
  --shadow-md: var(--shadow-2);
  --shadow-lg: var(--shadow-3);
  --shadow-xl: var(--shadow-3);
  --shadow-2xl: var(--shadow-3);

  --tracking-normal: 0em;
}

/* Base experience: make the theme own the canvas and native elements even in
   apps that never adopted semantic classes. Scoped to the theme wrapper. */
[class*="theme-"] {
  background-color: var(--bg);
  color: var(--fg);
  font-family: var(--font-body);
}
[class*="theme-"] :is(h1, h2, h3, h4) { font-family: var(--font-display); }
[class*="theme-"] :is(code, pre, kbd, samp) { font-family: var(--font-mono); }
[class*="theme-"] ::selection { background: color-mix(in oklab, var(--accent) 30%, transparent); }
